}

server {
  location / {
    proxy_pass http://backend_pool;
  }
}

// Producteur : publie un événement sans attendre qu'il soit traité
await queue.publish('commande.creee', { commandeId: 42, montant: 4500 });
console.log('Commande enregistrée, traitement en arrière-plan');

// Consommateur : traite les messages à son propre rythme
queue.subscribe('commande.creee', async (message) => {
  await envoyerEmailConfirmation(message.commandeId);
});

// Système CP (cohérence prioritaire) :
// en cas de coupure, le nœud minoritaire refuse d'écrire
if (!peutContacterMajorite()) throw new Error('Indisponible : cohérence impossible à garantir');

// Système AP (disponibilité prioritaire) :
// en cas de coupure, le nœud répond quand même, avec ses données locales
if (!peutContacterMajorite()) return donneesLocales; // potentiellement périmées

// Variante AP avec cohérence à terme (eventual consistency) :
// le nœud accepte l'écriture localement puis la synchronise plus tard
ecrireLocalement(donnee); planifierSynchronisation(donnee); // réconciliation différée

const db = new DatabaseClient(); // créé hors du handler, réutilisé entre invocations "chaudes"
export async function handler(event) {
  const { userId } = JSON.parse(event.body);
  const user = await db.user.findUnique({ where: { id: userId } });
  return {
    statusCode: 200,
    body: JSON.stringify(user),
  };
}
// Cette fonction ne tourne QUE pendant l'exécution d'une requête
